1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    :root {
9	      --color-white: #ffffff;
10	      --color-gold: #ffd700;
11	      --color-pink: #ff6b9d;
12	      --color-teal: #4ecdc4;
13	      --color-mint: #95e1d3;
14	      --shadow-color: rgba(0, 0, 0, 0.3);
15	      --transition-normal: 0.3s ease;
16	      --transition-slow: 0.6s ease-out;
17	    }
18	
19	    * {
20	      margin: 0;
21	      padding: 0;
22	      box-sizing: border-box;
23	    }
24	    html, body {
25	      width: 100%;
26	      height: 100%;
27	      overflow: hidden;
28	    }
29	    body {
30	      display: flex;
31	      flex-direction: column;
32	      justify-content: center;
33	      align-items: center;
34	      gap: 20px;
35	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
36	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
37	      color: var(--color-white);
38	      font-size: 14px;
39	      text-align: center;
40	      padding: 20px;
41	    }
42	    .circle-container {
43	      cursor: pointer;
44	      border: none;
45	      background: none;
46	      padding: 0;
47	      position: relative;
48	      will-change: transform;
49	    }
50	    .circle-container:hover,
51	    .circle-container:focus-visible {
52	      transform: scale(1.08);
53	    }
54	    .circle-container:focus {
55	      outline: none;
56	    }
57	    .circle-container:focus-visible {
58	      outline: 3px solid rgba(255, 255, 255, 0.7);
59	      outline-offset: 12px;
60	      border-radius: 50%;
61	    }
62	    svg {
63	      width: min(400px, 80vw);
64	      height: min(400px, 80vw);
65	      display: block;
66	      animation: fadeIn var(--transition-slow);
67	    }
68	    circle {
69	      fill: var(--color-white);
70	      stroke: rgba(255, 255, 255, 0.2);
71	      stroke-width: 2;
72	      animation: pulse 3s ease-in-out infinite;
73	      filter: drop-shadow(0 20px 40px var(--shadow-color));
74	      transition: fill var(--transition-normal), r 0.3s ease, stroke var(--transition-normal), filter var(--transition-normal);
75	    }
76	    .circle-container:hover circle,
77	    .circle-container:focus-visible circle {
78	      fill: #e8f4f8;
79	      r: 205;
80	      stroke: rgba(255, 255, 255, 0.4);
81	    }
82	    .circle-container.active circle {
83	      fill: var(--color-gold);
84	      stroke: rgba(255, 215, 0, 0.3);
85	      animation: pulse-active 0.6s ease-in-out;
86	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
87	    }
88	    .circle-container.active:hover circle {
89	      fill: #ffed4e;
90	    }
91	
92	    .circle-container.color-mode-1 circle {
93	      fill: var(--color-pink);
94	      stroke: rgba(255, 107, 157, 0.3);
95	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.3));
96	    }
97	    .circle-container.color-mode-1:hover circle,
98	    .circle-container.color-mode-1:focus-visible circle {
99	      stroke: rgba(255, 107, 157, 0.5);
100	    }
101	    .circle-container.color-mode-1.active circle {
102	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.5));
103	    }
104	
105	    .circle-container.color-mode-2 circle {
106	      fill: var(--color-teal);
107	      stroke: rgba(78, 205, 196, 0.3);
108	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.3));
109	    }
110	    .circle-container.color-mode-2:hover circle,
111	    .circle-container.color-mode-2:focus-visible circle {
112	      stroke: rgba(78, 205, 196, 0.5);
113	    }
114	    .circle-container.color-mode-2.active circle {
115	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.5));
116	    }
117	
118	    .circle-container.color-mode-3 circle {
119	      fill: var(--color-mint);
120	      stroke: rgba(149, 225, 211, 0.3);
121	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.3));
122	    }
123	    .circle-container.color-mode-3:hover circle,
124	    .circle-container.color-mode-3:focus-visible circle {
125	      stroke: rgba(149, 225, 211, 0.5);
126	    }
127	    .circle-container.color-mode-3.active circle {
128	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.5));
129	    }
130	
131	    .hint {
132	      font-size: 12px;
133	      opacity: 0.85;
134	      transition: opacity var(--transition-normal);
135	      letter-spacing: 0.5px;
136	      max-width: 90%;
137	    }
138	    .circle-container:hover ~ .hint,
139	    .circle-container:focus-visible ~ .hint {
140	      opacity: 1;
141	    }
142	
143	    .mode-indicator {
144	      font-size: 10px;
145	      opacity: 0;
146	      margin-top: 8px;
147	      letter-spacing: 1px;
148	      text-transform: uppercase;
149	      transition: opacity var(--transition-normal);
150	      height: 16px;
151	    }
152	    .mode-indicator.visible {
153	      opacity: 0.9;
154	    }
155	
156	    .controls {
157	      display: flex;
158	      gap: 12px;
159	      margin-top: 8px;
160	    }
161	
162	    .control-btn {
163	      padding: 8px 16px;
164	      font-size: 11px;
165	      font-weight: 600;
166	      letter-spacing: 0.5px;
167	      text-transform: uppercase;
168	      background: rgba(255, 255, 255, 0.15);
169	      color: var(--color-white);
170	      border: 1px solid rgba(255, 255, 255, 0.3);
171	      border-radius: 20px;
172	      cursor: pointer;
173	      transition: all var(--transition-normal);
174	      backdrop-filter: blur(4px);
175	      will-change: transform;
176	    }
177	
178	    .control-btn:hover {
179	      background: rgba(255, 255, 255, 0.25);
180	      border-color: rgba(255, 255, 255, 0.5);
181	      transform: translateY(-2px);
182	    }
183	
184	    .control-btn:active {
185	      transform: scale(0.95);
186	    }
187	
188	    .control-btn:focus {
189	      outline: none;
190	    }
191	
192	    .control-btn:focus-visible {
193	      outline: 2px solid rgba(255, 255, 255, 0.7);
194	      outline-offset: 4px;
195	    }
196	    @keyframes pulse {
197	      0%, 100% { r: 200; }
198	      50% { r: 202; }
199	    }
200	    @keyframes pulse-active {
201	      0% { r: 200; }
202	      50% { r: 210; }
203	      100% { r: 200; }
204	    }
205	    @keyframes fadeIn {
206	      from { opacity: 0; transform: scale(0.9); }
207	      to { opacity: 1; transform: scale(1); }
208	    }
209	    @keyframes colorShift {
210	      0% { filter: brightness(1); }
211	      50% { filter: brightness(1.2); }
212	      100% { filter: brightness(1); }
213	    }
214	    .color-shifting circle {
215	      animation: colorShift 0.6s ease-out;
216	    }
217	    @media (max-width: 480px) {
218	      body {
219	        gap: 16px;
220	      }
221	      .hint {
222	        font-size: 11px;
223	      }
224	      .mode-indicator {
225	        font-size: 9px;
226	      }
227	    }
228	    @media (prefers-reduced-motion: reduce) {
229	      * {
230	        animation: none !important;
231	        transition: none !important;
232	      }
233	    }
234	  </style>
235	</head>
236	<body>
237	  <main style="text-align: center;">
238	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle">
239	      <svg viewBox="0 0 400 400" aria-hidden="true">
240	        <circle cx="200" cy="200" r="200"/>
241	      </svg>
242	    </button>
243	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
244	    <div class="controls">
245	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
246	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
247	    </div>
248	  </main>
249	  <div class="hint" id="hint-text" role="status" aria-live="polite">Click to activate • Double-click to change color</div>
250	
251	  <script>
252	    const STORAGE_KEY = 'circle-state';
253	    const COLOR_MODES = ['default', 'color-mode-1', 'color-mode-2', 'color-mode-3'];
254	    const COLOR_NAMES = ['Default White', 'Pink', 'Teal', 'Mint'];
255	
256	    const circle = document.getElementById('decorative-circle');
257	    const hint = document.getElementById('hint-text');
258	    const modeIndicator = document.getElementById('mode-indicator');
259	    const cycleBtn = document.getElementById('cycle-btn');
260	    const resetBtn = document.getElementById('reset-btn');
261	
262	    let state = { active: false, colorMode: 0 };
263	    let lastTapTime = 0;
264	    const TAP_DELAY = 300;
265	
266	    const saveState = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
267	
268	    const loadState = () => {
269	      try {
270	        const saved = localStorage.getItem(STORAGE_KEY);
271	        if (saved) state = JSON.parse(saved);
272	      } catch (e) {
273	        console.warn('Failed to load state');
274	      }
275	      applyState();
276	    };
277	
278	    const applyState = () => {
279	      circle.classList.remove('active', ...COLOR_MODES);
280	      if (state.active) circle.classList.add('active');
281	      if (state.colorMode > 0) circle.classList.add(COLOR_MODES[state.colorMode]);
282	      updateUI();
283	    };
284	
285	    const toggleActive = () => {
286	      state.active = !state.active;
287	      applyState();
288	      saveState();
289	    };
290	
291	    const cycleColor = () => {
292	      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
293	      state.active = true;
294	      circle.classList.add('color-shifting');
295	      setTimeout(() => circle.classList.remove('color-shifting'), 600);
296	      applyState();
297	      saveState();
298	    };
299	
300	    const resetState = () => {
301	      state = { active: false, colorMode: 0 };
302	      applyState();
303	      saveState();
304	    };
305	
306	    const updateUI = () => {
307	      const hints = state.active
308	        ? ['Active!', 'Press C or click Cycle Color to change color', 'Press R or click Reset to return to default']
309	        : ['Click to activate', 'Double-click or press C to cycle color', 'Press R or click Reset to reset'];
310	      hint.textContent = hints.join(' • ');
311	
312	      if (state.active && state.colorMode > 0) {
313	        modeIndicator.textContent = COLOR_NAMES[state.colorMode];
314	        modeIndicator.classList.add('visible');
315	      } else {
316	        modeIndicator.classList.remove('visible');
317	      }
318	    };
319	
320	    circle.addEventListener('click', toggleActive);
321	    circle.addEventListener('dblclick', (e) => {
322	      e.preventDefault();
323	      cycleColor();
324	    });
325	
326	    circle.addEventListener('touchend', (e) => {
327	      const currentTime = Date.now();
328	      const tapLength = currentTime - lastTapTime;
329	      if (tapLength < TAP_DELAY && tapLength > 0) {
330	        e.preventDefault();
331	        cycleColor();
332	      } else {
333	        lastTapTime = currentTime;
334	      }
335	    });
336	
337	    circle.addEventListener('keydown', (e) => {
338	      const key = e.key.toLowerCase();
339	      if (key === ' ' || key === 'enter') {
340	        e.preventDefault();
341	        toggleActive();
342	      } else if (key === 'c') {
343	        e.preventDefault();
344	        cycleColor();
345	      } else if (key === 'r') {
346	        e.preventDefault();
347	        resetState();
348	      }
349	    });
350	
351	    cycleBtn.addEventListener('click', cycleColor);
352	    resetBtn.addEventListener('click', resetState);
353	
354	    loadState();
355	    circle.focus();
356	  </script>
357	</body>
358	</html>
